  "edit-pdf.redrawing.the.edited.paragraphs.instead.6f9592": "इसके बजाय एडिट किए गए पैराग्राफ़ फिर से बनाए जा रहे हैं…",
  "edit-pdf.edited.pdf.preview.ready.unlock.to.save.3b563b": "एडिट किया गया PDF प्रीव्यू तैयार है। एडिट की गई फ़ाइल को सेव करने के लिए अनलॉक करें। आपके बदलाव अभी भी यहाँ मौजूद हैं।",
  "edit-pdf.edited.pdf.ready.with.of.edited.paragraphs.cab23a": {
    "one": "एडिट किया गया PDF तैयार है। एडिट किए गए पैराग्राफ़ लिखे गए: {v0} / {v1}। {v2} इसमें आपके बदलाव अभी भी यहाँ मौजूद हैं।{v4}",
    "other": "एडिट किया गया PDF तैयार है। एडिट किए गए पैराग्राफ़ लिखे गए: {v0} / {v1}। {v2} इनमें आपके बदलाव अभी भी यहाँ मौजूद हैं।{v4}"
  },
  "edit-pdf.edited.pdf.ready.but.your.old.wording.8cfe80": "एडिट किया गया PDF तैयार है — लेकिन आपके पुराने शब्द अभी भी नए टेक्स्ट के नीचे फ़ाइल में मौजूद हैं, जहाँ खोजने पर वे मिल सकते हैं। कोई भी निजी जानकारी शेयर करने से पहले इसकी जांच कर लें।",
  "edit-pdf.edited.pdf.ready.the.paragraphs.you.changed.9cebe8": "एडिट किया गया PDF तैयार है। आपके द्वारा बदले गए पैराग्राफ़ फिर से बनाए गए हैं, इसलिए उनके अक्षर पेज के बाकी हिस्सों से थोड़े अलग दिख सकते हैं। आपके पुराने शब्द हटा दिए गए हैं। शेयर करने से पहले एक बार देख लें।",
  "edit-pdf.edited.pdf.ready.review.it.before.sharing.0b2900": "एडिट किया गया PDF तैयार है। शेयर करने से पहले इसकी समीक्षा करें।",
  "edit-pdf.save.cancelled.your.edits.are.still.here.433678": "सेव करना रद्द किया गया। आपके बदलाव अभी भी यहाँ मौजूद हैं।",
