  "metadata-pdf.this.empties.the.six.boxes.below.other.dba172": "इससे नीचे के छह बॉक्स खाली हो जाते हैं। बाकी छिपी जानकारी — टिप्पणियां, अटैचमेंट, फ़ॉर्म में आपने जो भी टाइप किया — फ़ाइल में बनी रहती है। “PDF साफ़ करें” दस्तावेज़ का विवरण, टिप्पणियां और लिंक हटाता है; यह फ़ॉर्म की वैल्यू नहीं मिटाता।",
