  "help-page.processing.is.unlimited.on.ios.the.first.90908e": "प्रोसेसिंग असीमित है. iOS पर, प्रत्येक 7-दिवसीय रोलिंग कोटा अवधि में पहले पांच सफल कार्य पूरे कार्य होते हैं जिन्हें सेव, शेयर और एक्सपोर्ट किया जा सकता है. यह अवधि पहले सफल कार्य के साथ शुरू होती है. पांच सफल कार्यों के बाद, प्रोसेसिंग और पूर्वावलोकन उपलब्ध रहते हैं, लेकिन कोटा रीसेट होने तक सेव, शेयर और एक्सपोर्ट करने के लिए Pro आवश्यक है. Apple Pro की खरीदारियां संभालता है.",
